use super::*;
use crate::settings::EffectFixture;
use serde_json::json;
use std::{fs,cell::Cell};
fn target()->Destinations{Destinations{revision:"fixture-config".into(),values:json!({"pets":{"ai_ollama":{"provider":"ollama","model":"explicit-fixture"}}})}}
fn setup()->(EffectFixture,Controller,Owner){let f=EffectFixture::new();f.external();let c=Controller::default();let owner=c.register();(f,c,owner)}
fn request(p:&Preview)->Decision{serde_json::from_value(json!({"token":p.token,"fingerprint":p.fingerprint,"reviewedAllValues":true,"understandPriorUncertainty":true,"keepComponentsSuspended":true,"acceptRecoveredValues":true})).unwrap()}
fn prepare(c:&Controller,o:&Owner,f:&EffectFixture)->Preview{c.prepare(o,&f.current,&f.path,target(),false).unwrap()}
#[test]fn review_controller_preparation_is_passive_and_does_not_query_or_create_authority(){let(f,c,o)=setup();let original=fs::read(&f.path).unwrap();let p=prepare(&c,&o,&f);assert_eq!(p.scope,"dataOnlyKeepComponentsSuspended");assert_eq!(p.suspended_operations.len(),6);assert_eq!(fs::read(&f.path).unwrap(),original);assert_eq!(fs::read_dir(&f.root).unwrap().count(),1);}
#[test]fn review_controller_adopts_only_captured_data_and_does_not_reactivate_components_or_replay(){let(f,c,o)=setup();let mut p=prepare(&c,&o,&f);let actual=p.values["model"].clone();p.values["model"]=json!("renderer-chosen-other-provider");let(fresh,r)=c.apply(&o,&f.current,request(&p),||Ok(target()),||true).unwrap();assert!(r.data_adopted);assert_eq!(json!(fresh.model),actual);assert_eq!(r.status.phase,IoPhase::Ready);for op in durable::OPERATIONS{assert!(f.probe.operation(op).is_err());}let record=fs::read(f.root.join(durable::FILE)).unwrap();assert!(c.apply(&o,&f.current,request(&p),||Ok(target()),||true).is_err());assert_eq!(fs::read(f.root.join(durable::FILE)).unwrap(),record);}
#[test]fn review_controller_changed_source_memory_journal_or_destination_is_refused_before_publication(){for variant in 0..4{let(f,c,o)=setup();let p=prepare(&c,&o,&f);match variant{0=>{let mut v:Value=serde_json::from_slice(&fs::read(&f.path).unwrap()).unwrap();v["model"]=json!("new-unreviewed-model");fs::write(&f.path,serde_json::to_vec(&v).unwrap()).unwrap();},1=>{f.current.lock().unwrap().model="unreviewed-memory-change".into();},2=>{fs::write(f.root.join(durable::FILE),b"malformed-new-record").unwrap();},_=>{}}let before=fs::read(&f.path).unwrap();let result=c.apply(&o,&f.current,request(&p),||if variant==3{Ok(Destinations{revision:"changed".into(),values:target().values})}else{Ok(target())},||true);assert!(result.is_err(),"variant{variant}");assert_eq!(fs::read(&f.path).unwrap(),before);assert!(!f.root.join(history::DIRECTORY).exists());}}
#[test]fn review_controller_expiry_window_close_recreation_and_hidden_window_refuse_without_effects(){for variant in 0..4{let(f,c,o)=setup();let p=prepare(&c,&o,&f);match variant{0=>{c.state.lock().unwrap().slot.as_mut().unwrap().pending.as_mut().unwrap().expires=Instant::now()-Duration::from_secs(1);},1=>o.invalidate(),2=>{c.register();},_=>{}}let before=fs::read(&f.path).unwrap();assert!(c.apply(&o,&f.current,request(&p),||Ok(target()),||variant!=3).is_err());assert_eq!(fs::read(&f.path).unwrap(),before);assert!(!f.root.join(history::DIRECTORY).exists());}}
#[test]fn review_controller_acknowledgements_and_arguments_cannot_authorize_another_candidate(){let(f,c,o)=setup();let p=prepare(&c,&o,&f);let mut r=request(&p);r.keep_components_suspended=false;assert!(c.apply(&o,&f.current,r,||Ok(target()),||true).is_err());let mut r=request(&p);r.fingerprint="0".repeat(64);assert!(c.apply(&o,&f.current,r,||Ok(target()),||true).is_err());let mut value=serde_json::to_value(&p).unwrap();value["activateAll"]=json!(true);assert!(serde_json::from_value::<Decision>(value).is_err());assert!(!f.root.join(history::DIRECTORY).exists());}
#[test]fn review_controller_cancel_is_one_use_and_does_not_renew_any_authority(){let(f,c,o)=setup();let p=prepare(&c,&o,&f);c.cancel(&o,Cancellation{token:p.token.clone(),fingerprint:p.fingerprint.clone()}).unwrap();assert!(c.apply(&o,&f.current,request(&p),||Ok(target()),||true).is_err());assert!(!f.root.join(history::DIRECTORY).exists());}
#[test]fn review_controller_revocation_while_destination_io_waits_prevents_settings_rename(){let(f,c,o)=setup();let p=prepare(&c,&o,&f);let before=fs::read(&f.path).unwrap();let hit=Cell::new(false);let result=c.apply(&o,&f.current,request(&p),||{if fs::read(f.root.join(durable::FILE)).ok().and_then(|b|serde_json::from_slice::<Value>(&b).ok()).is_some_and(|v|v["phase"]=="prepared"){hit.set(true);o.invalidate();}Ok(target())},||true);assert!(hit.get());assert!(result.is_err());assert_eq!(fs::read(&f.path).unwrap(),before);assert!(!f.probe.status().new_effects_allowed);let record:Value=serde_json::from_slice(&fs::read(f.root.join(durable::FILE)).unwrap()).unwrap();assert_eq!(record["phase"],"notPublished");assert_eq!(record["reviewRequired"],true);}
#[test]fn review_controller_unknown_fields_survive_valid_data_adoption_and_malformed_originals_are_retained(){for invalid in [false,true]{let(f,c,o)=setup();let original=if invalid{br#"{"model":"explicit-recovery","soundVolume":"invalid","unrecognized":{"note":"retain exact bytes"}}"#.to_vec()}else{let mut v:Value=serde_json::from_slice(&fs::read(&f.path).unwrap()).unwrap();v["unrecognized"]=json!({"note":"retain exact bytes"});serde_json::to_vec(&v).unwrap()};fs::write(&f.path,&original).unwrap();let p=prepare(&c,&o,&f);assert_eq!(p.will_preserve_current_bytes,!invalid);assert_eq!(p.unknown_field_count,1);if invalid{assert!(p.defaulted_fields.contains(&"soundVolume".into()));}let(_,receipt)=c.apply(&o,&f.current,request(&p),||Ok(target()),||true).unwrap();let artifact:Value=serde_json::from_slice(&fs::read(f.root.join(history::DIRECTORY).join(format!("review-{}.json",receipt.retained_review))).unwrap()).unwrap();assert_eq!(artifact["originalSettings"],original.iter().map(|v|format!("{v:02x}")).collect::<String>());if !invalid{assert_eq!(fs::read(&f.path).unwrap(),original);}}}

#[test]fn review_controller_cancel_during_writer_wait_is_priority_and_does_not_assume_worker_terminated(){
 let(f,c,o)=setup();let p=prepare(&c,&o,&f);let c=Arc::new(c);let owner=o.clone();let current=f.current.clone();let original=fs::read(&f.path).unwrap();let decision=request(&p);let held=f.current.lock().unwrap();let worker=c.clone();
 let thread=std::thread::spawn(move||worker.apply(&owner,&current,decision,||Ok(target()),||true));
 let until=Instant::now()+Duration::from_secs(2);while c.state.lock().unwrap().slot.as_ref().is_none_or(|s|s.pending.is_some()){assert!(Instant::now()<until);std::thread::sleep(Duration::from_millis(2));}
 c.cancel(&o,Cancellation{token:p.token.clone(),fingerprint:p.fingerprint.clone()}).unwrap();assert!(c.state.lock().unwrap().slot.as_ref().is_some_and(|s|s.pending.is_none()));assert!(!thread.is_finished());drop(held);assert!(thread.join().unwrap().is_err());assert!(c.state.lock().unwrap().slot.is_none());assert_eq!(fs::read(&f.path).unwrap(),original);assert!(!f.root.join(history::DIRECTORY).exists());
}
#[test]fn review_controller_changed_data_still_reports_prior_recovery_from_exact_io_record(){
 let(f,c,o)=setup();let path=f.path.clone();let original=br#"{"model":"explicit-fixture","soundVolume":"invalid"}"#;fs::write(&path,original).unwrap();*f.current.lock().unwrap()=crate::settings::load_from(&path);
 crate::settings::update_with(&f.current,|s|s.sound_volume=0.4,|s|crate::settings::save_to(&path,s),|_|{}).unwrap();f.external();let p=prepare(&c,&o,&f);assert_eq!(p.observed_phase,"Changed");assert!(p.prior_recovery_provenance_uncertain);let mut decision=request(&p);decision.accept_recovered_values=false;assert!(c.apply(&o,&f.current,decision,||Ok(target()),||true).is_err());
}

#[test]fn review_controller_incomplete_compatible_settings_freeze_reviewed_defaults_and_keep_opaque_fields(){
 let(f,c,o)=setup();let original=br#"{"model":"explicit-keep-model","opaqueFutureData":{"note":"retain"}}"#;fs::write(&f.path,original).unwrap();let p=prepare(&c,&o,&f);assert!(!p.will_preserve_current_bytes);assert!(!p.defaulted_fields.is_empty());let(_,receipt)=c.apply(&o,&f.current,request(&p),||Ok(target()),||true).unwrap();let data:Value=serde_json::from_slice(&fs::read(&f.path).unwrap()).unwrap();assert_eq!(data["opaqueFutureData"]["note"],"retain");assert_eq!(data["model"],"explicit-keep-model");assert!(p.values.as_object().unwrap().keys().all(|key|data.get(key).is_some()));assert_eq!(receipt.status.phase,IoPhase::Ready);
}
#[test]fn review_controller_restored_profile_preserves_original_and_publishes_its_exact_canonical_field_set(){
 for original in [br#"{"model":"explicit-keep-model","opaqueFutureData":{"note":"retain"}}"#.as_slice(),br#"{"model":"explicit-keep-model","soundVolume":"invalid"}"#.as_slice()]{let(f,c,o)=setup();fs::write(&f.path,original).unwrap();let p=c.prepare(&o,&f.current,&f.path,target(),true).unwrap();assert!(!p.will_preserve_current_bytes);let(_,receipt)=c.apply(&o,&f.current,request(&p),||Ok(target()),||true).unwrap();let strict=crate::settings::read_initialized(&f.path).unwrap();assert_eq!(strict.model,"explicit-keep-model");let artifact:Value=serde_json::from_slice(&fs::read(f.root.join(history::DIRECTORY).join(format!("review-{}.json",receipt.retained_review))).unwrap()).unwrap();assert_eq!(artifact["originalSettings"],original.iter().map(|v|format!("{v:02x}")).collect::<String>());}
}
